import { ReactNode } from 'react'
import { Box, Group } from '@mantine/core'

interface Props {
  children: ReactNode
}

// Full-width toolbar strip above a mode's main content. Shared by Split and
// Drive Upload mode; Merge mode's toolbar has a different shape (full-height
// side columns) and doesn't fit this.
export default function Toolbar({ children }: Props) {
  return (
    <Box
      style={{
        flexShrink: 0,
        borderBottom: '1px solid var(--mantine-color-gray-3)',
        display: 'flex',
        alignItems: 'center',
        paddingInline: 12,
        height: 44,
      }}
    >
      <Group gap={8} style={{ width: '100%' }}>
        {children}
      </Group>
    </Box>
  )
}

import { useState } from 'react'
import { Box, Group, Tabs, Text } from '@mantine/core'
import MergeMode from './components/MergeMode'
import SplitMode from './components/SplitMode'
import DriveUploadMode from './components/DriveUploadMode'

type AppMode = 'split' | 'merge' | 'drive'

export default function App() {
  const [mode, setMode] = useState<AppMode>('split')
  const [splitInitialPath, setSplitInitialPath] = useState<string | null>(null)

  const handleOpenInSplitMode = (path: string) => {
    setSplitInitialPath(path)
    setMode('split')
  }

  return (
    <Box style={{ display: 'flex', flexDirection: 'column', height: '100vh', overflow: 'hidden' }}>
      <Box
        component="header"
        style={{
          height: 48,
          flexShrink: 0,
          borderBottom: '1px solid var(--mantine-color-gray-3)',
          display: 'flex',
          alignItems: 'center',
          paddingInline: 'var(--mantine-spacing-md)',
        }}
      >
        <Group justify="space-between" style={{ width: '100%' }}>
          <Text fw={600} size="sm">Paper Scan Processor</Text>
          <Tabs value={mode} onChange={(v) => v && setMode(v as AppMode)}>
            <Tabs.List>
              <Tabs.Tab value="split">Split</Tabs.Tab>
              <Tabs.Tab value="merge">Merge</Tabs.Tab>
              <Tabs.Tab value="drive">Drive Upload</Tabs.Tab>
            </Tabs.List>
          </Tabs>
        </Group>
      </Box>
      <Box style={{ flex: 1, overflow: 'hidden' }}>
        {mode === 'split' && <SplitMode initialPath={splitInitialPath} />}
        {mode === 'merge' && <MergeMode onOpenInSplitMode={handleOpenInSplitMode} />}
        {mode === 'drive' && <DriveUploadMode />}
      </Box>
    </Box>
  )
}

import { useRef, useEffect } from 'react'
import { TransformWrapper, TransformComponent, ReactZoomPanPinchRef } from 'react-zoom-pan-pinch'
import { Center, Loader } from '@mantine/core'
import * as pageCache from '../lib/pageCache'

const DETAIL_WIDTH = 1400

interface Props {
  pdfPath: string
  pageNum: number
  pageCount: number
  rotation?: number
  onToggleSkip?: () => void
  onRotate?: (delta: 90 | -90) => void
}

export default function DetailPanel({ pdfPath, pageNum, pageCount, rotation = 0, onToggleSkip, onRotate }: Props) {
  pageCache.usePageCacheRender()
  const transformRef = useRef<ReactZoomPanPinchRef>(null)

  useEffect(() => {
    pageCache.load(pdfPath, pageNum, DETAIL_WIDTH)
    if (pageNum > 1) pageCache.load(pdfPath, pageNum - 1, DETAIL_WIDTH) // prefetch previous page
    if (pageNum < pageCount) pageCache.load(pdfPath, pageNum + 1, DETAIL_WIDTH) // prefetch next page
  }, [pdfPath, pageNum, pageCount])

  useEffect(() => {
    transformRef.current?.resetTransform()
  }, [pageNum, rotation])

  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) return
      if (e.key.toLowerCase() !== 'r') return
      e.preventDefault()
      onRotate?.(e.shiftKey ? -90 : 90)
    }
    window.addEventListener('keydown', handler)
    return () => window.removeEventListener('keydown', handler)
  }, [onRotate])

  const cachedWidth = pageCache.getCachedWidth(pdfPath, pageNum)
  const src = cachedWidth !== undefined && cachedWidth >= DETAIL_WIDTH
    ? pageCache.getSrc(pdfPath, pageNum)
    : undefined

  return (
    <div
      style={{
        flex: 1,
        height: '100%',
        overflow: 'hidden',
        position: 'relative',
        background: 'var(--mantine-color-gray-1)',
        padding: 8,
      }}
    >
      {pageCache.isLoading(pdfPath, pageNum) && (
        <Center style={{ position: 'absolute', inset: 0, zIndex: 1 }}>
          <Loader />
        </Center>
      )}
      {src && (
        <TransformWrapper ref={transformRef} centerOnInit minScale={0.1} maxScale={8}>
          <TransformComponent
            wrapperStyle={{ width: '100%', height: '100%' }}
            contentStyle={{ display: 'flex', alignItems: 'center', justifyContent: 'center' }}
          >
            <img
              src={src}
              alt={`Page ${pageNum}`}
              draggable={false}
              style={{ maxWidth: '100%', maxHeight: '100%', display: 'block', userSelect: 'none', transform: rotation ? `rotate(${rotation}deg)` : undefined }}
            />
          </TransformComponent>
        </TransformWrapper>
      )}
    </div>
  )
}

