1	import { useState, useEffect, useCallback } from 'react'
2	import { Box, Button, Divider, Group, Modal, Stack, Text, TextInput } from '@mantine/core'
3	import { notifications } from '@mantine/notifications'
4	import ThumbnailPanel from './ThumbnailPanel'
5	import DetailPanel from '../DetailPanel'
6	import Toolbar from '../Toolbar'
7	import { OpenFile, OpenPDF, PageCount, PickFolder, ExportSplit, CheckConflicts, DeleteFile } from '../../../wailsjs/go/main/App'
8	import { ellipsisPath } from '../../utils'
9	import { useOutputFiles } from './useOutputFiles'
10	import { usePendingFocus } from './usePendingFocus'
11	import * as pageCache from '../../lib/pageCache'
12	
13	const DEFAULT_TEMPLATE = '{date} {name}'
14	
15	function applyTemplate(template: string): { value: string; cursorPos: number } {
16	  const date = new Date().toISOString().split('T')[0]
17	  const withDate = template.replace('{date}', date)
18	  const nameIdx = withDate.indexOf('{name}')
19	  if (nameIdx === -1) return { value: withDate, cursorPos: withDate.length }
20	  return { value: withDate.replace('{name}', ''), cursorPos: nameIdx }
21	}
22	
23	interface Props {
24	  initialPath?: string | null
25	}
26	
27	export default function SplitMode({ initialPath }: Props) {
28	  const [pdfPath, setPdfPath] = useState<string | null>(null)
29	  const [pageCount, setPageCount] = useState(0)
30	  const [pageOrder, setPageOrder] = useState<number[]>([])
31	  const [selectedPage, setSelectedPage] = useState(1)
32	  const [outputFolder, setOutputFolder] = useState<string | null>(null)
33	  const [successModal, setSuccessModal] = useState<{show: boolean, outputPath: string, inputPath: string}>({show: false, outputPath: '', inputPath: ''})
34	  const outputFiles = useOutputFiles(outputFolder)
35	  const focus = usePendingFocus()
36	  const [template, setTemplate] = useState(DEFAULT_TEMPLATE)
37	  const [exporting, setExporting] = useState(false)
38	  const [rotations, setRotations] = useState<Map<number, number>>(() => new Map())
39	  const [skipped, setSkipped] = useState<Set<number>>(() => new Set())
40	
41	  useEffect(() => {
42	    return () => {
43	      if (pdfPath) pageCache.evict(pdfPath)
44	    }
45	  }, [pdfPath])
46	
47	  const rotate = (page: number, delta: 90 | -90 = 90) => {
48	    setRotations(prev => {
49	      const next = new Map(prev)
50	      const deg = ((next.get(page) ?? 0) + delta + 360) % 360
51	      if (deg === 0) next.delete(page); else next.set(page, deg)
52	      return next
53	    })
54	  }
55	
56	  const toggleSkip = (page: number) => {
57	    setSkipped(prev => {
58	      const next = new Set(prev)
59	      if (next.has(page)) next.delete(page); else next.add(page)
60	      return next
61	    })
62	  }
63	
64	  const movePage = (fromPos: number, toPos: number) => {
65	    setPageOrder(prev => {
66	      const next = [...prev]
67	      const [page] = next.splice(fromPos, 1)
68	      next.splice(toPos, 0, page)
69	      return next
70	    })
71	  }
72	
73	  const resetForFile = (count: number, path: string, tmpl: string) => {
74	    setPdfPath(path)
75	    setPageCount(count)
76	    setPageOrder(Array.from({ length: count }, (_, i) => i + 1))
77	    setSelectedPage(1)
78	    setRotations(new Map())
79	    setSkipped(new Set())
80	    outputFiles.reset(applyTemplate(tmpl).value)
81	    focus.clear()
82	  }
83	
84	  useEffect(() => {
85	    if (!initialPath) return
86	    PageCount(initialPath)
87	      .then(count => resetForFile(count, initialPath, template))
88	      .catch(e => notifications.show({ title: 'Failed to open file', message: String(e), color: 'red' }))
89	  }, [initialPath])
90	
91	  const handleOpen = async () => {
92	    const path = await OpenPDF()
93	    if (!path) return
94	    try {
95	      const count = await PageCount(path)
96	      resetForFile(count, path, template)
97	    } catch (e) {
98	      notifications.show({ title: 'Failed to open file', message: String(e), color: 'red' })
99	    }
100	  }
101	
102	  const handlePickOutputFolder = async () => {
103	    const folder = await PickFolder('Choose Output Folder')
104	    if (folder) setOutputFolder(folder)
105	  }
106	
107	  const handleExport = async () => {
108	    if (!pdfPath || !outputFolder) return
109	    setExporting(true)
110	    try {
111	      const sortedStarts = [...outputFiles.all.keys()].sort((a, b) => a - b)
112	      const files = sortedStarts.map((firstPos, i) => {
113	        const nextPos = sortedStarts[i + 1] ?? pageOrder.length
114	        const pages = pageOrder.slice(firstPos, nextPos).filter(p => !skipped.has(p))
115	        const f = outputFiles.all.get(firstPos)!
116	        return { pages, name: f.name, outDir: f.folderOverride ?? outputFolder! }
117	      })
118	      const conflicts = await CheckConflicts(files)
119	      if (conflicts.length > 0) {
120	        const names = conflicts.map(p => p.split('/').pop()).join(', ')
121	        notifications.show({ title: 'Filename conflict', message: `Already exists: ${names}`, color: 'orange', autoClose: false })
122	        return
123	      }
124	      await ExportSplit(pdfPath, files, Object.fromEntries(rotations))
125	      setSuccessModal({show: true, outputPath: outputFolder, inputPath: pdfPath})
126	    } catch (e) {
127	      notifications.show({ title: 'Export failed', message: String(e), color: 'red' })
128	    } finally {
129	      setExporting(false)
130	    }
131	  }
132	
133	  const closeSuccessModal = () => setSuccessModal({show: false, outputPath: '', inputPath: ''})
134	
135	  const handleDeleteInput = async () => {
136	    const { inputPath } = successModal
137	    closeSuccessModal()
138	    setPdfPath(null)
139	    try {
140	      await DeleteFile(inputPath)
141	    } catch (e) {
142	      notifications.show({ title: 'Failed to delete file', message: String(e), color: 'red' })
143	    }
144	  }
145	
146	  const handleToggleSplitPoint = useCallback((afterPosition: number) => {
147	    const prefill = applyTemplate(template)
148	    const added = outputFiles.toggle(afterPosition, prefill.value)
149	    if (added) focus.request(afterPosition, prefill.cursorPos)
150	    else focus.clear()
151	  }, [template, outputFiles.toggle])
152	
153	  return (
154	    <Box style={{ display: 'flex', flexDirection: 'column', height: '100%' }}>
155	      <Modal opened={successModal.show} onClose={closeSuccessModal} title="Export complete" centered>
156	        <Stack gap="md">
157	          <Group>
158	            <Text size="sm" c="dimmed" style={{ flex: 1 }}>{successModal.outputPath}</Text>
159	            <Button size="xs" variant="default" onClick={() => OpenFile(successModal.outputPath)}>
