import { useEffect, useState } from 'react'
import { Box, Button, Group, Loader, Modal, Text } from '@mantine/core'
import { ListDriveFolder } from '../../../wailsjs/go/main/App'
import { DriveAssignment } from './useDriveAssignments'

interface DriveFolder {
  id: string
  name: string
}

const ROOT: DriveFolder = { id: 'root', name: '/' }
const INDENT_PER_LEVEL = 16

interface DriveTreeNodeProps {
  item: DriveFolder
  path: string
  selectedId: string | null
  onSelect: (item: DriveFolder, path: string) => void
  defaultExpanded?: boolean
}

function DriveTreeNode({ item, path, selectedId, onSelect, defaultExpanded }: DriveTreeNodeProps) {
  const [expanded, setExpanded] = useState(defaultExpanded ?? false)
  const [children, setChildren] = useState<DriveFolder[] | null>(null)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const load = async () => {
    setLoading(true)
    setError(null)
    try {
      const items = await ListDriveFolder(item.id)
      setChildren(items.filter(i => i.isFolder).map(i => ({ id: i.id, name: i.name })))
    } catch (e) {
      setError(String(e))
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    if (defaultExpanded && children === null) load()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  const toggle = () => {
    if (!expanded && children === null) load()
    setExpanded(prev => !prev)
  }

  return (
    <Box>
      <Group gap={4} wrap="nowrap">
        <button
          type="button"
          onClick={toggle}
          aria-expanded={expanded}
          aria-label={expanded ? `Collapse ${item.name}` : `Expand ${item.name}`}
          style={{ width: 16, flexShrink: 0, border: 'none', background: 'transparent', padding: 0, cursor: 'pointer' }}
        >
          {loading ? <Loader size={10} /> : <Text size="xs" c="dimmed">{expanded ? '▼' : '▶'}</Text>}
        </button>
        <button
          type="button"
          onClick={() => onSelect(item, path)}
          style={{
            flex: 1,
            textAlign: 'left',
            border: 'none',
            padding: '2px 6px',
            borderRadius: 4,
            cursor: 'pointer',
            fontFamily: 'inherit',
            background: item.id === selectedId ? 'var(--mantine-color-blue-1)' : 'transparent',
          }}
        >
          <Text size="sm" fw={item.id === selectedId ? 600 : 400}>📁 {item.name}</Text>
        </button>
      </Group>
      {error && <Text size="xs" c="red" pl={INDENT_PER_LEVEL + 6}>{error}</Text>}
      {expanded && children && (
        <Box pl={INDENT_PER_LEVEL}>
          {children.length === 0
            ? <Text size="xs" c="dimmed" pl={6}>No subfolders</Text>
            : children.map(child => (
                <DriveTreeNode
                  key={child.id}
                  item={child}
                  path={path.endsWith('/') ? `${path}${child.name}` : `${path}/${child.name}`}
                  selectedId={selectedId}
                  onSelect={onSelect}
                />
              ))}
        </Box>
      )}
    </Box>
  )
}

interface Props {
  opened: boolean
  onClose: () => void
  onSelect: (folder: DriveAssignment) => void
}

export default function DriveFolderPickerModal({ opened, onClose, onSelect }: Props) {
  const [selected, setSelected] = useState<{ id: string; name: string; path: string } | null>(null)

  useEffect(() => {
    if (!opened) setSelected(null)
  }, [opened])

  const confirm = () => {
    if (!selected) return
    onSelect({ driveFolderId: selected.id, path: selected.path })
    onClose()
  }

  return (
    <Modal opened={opened} onClose={onClose} title="Choose a Drive folder" size="md">
      <Box style={{ maxHeight: 400, overflowY: 'auto' }}>
        <DriveTreeNode
          item={ROOT}
          path={ROOT.name}
          selectedId={selected?.id ?? null}
          onSelect={(item, path) => setSelected({ id: item.id, name: item.name, path })}
          defaultExpanded
        />
      </Box>
      <Group justify="flex-end" mt="md">
        <Button variant="default" onClick={onClose}>Cancel</Button>
        <Button disabled={!selected} onClick={confirm}>
          {selected ? `Select "${selected.name}"` : 'Select'}
        </Button>
      </Group>
    </Modal>
  )
}

import { useRef, useState, useEffect } from 'react'
import { useVirtualizer } from '@tanstack/react-virtual'
import { Box, Text } from '@mantine/core'
import * as pageCache from '../../lib/pageCache'
import { makeResizeDragHandler } from '../../lib/resizableWidth'
import { DEFAULT_WIDTH, DRAG_HANDLE_WIDTH, ITEM_PADDING, LABEL_HEIGHT, PAGE_ASPECT } from '../../constants'
import PageThumbnail from '../PageThumbnail'

const MIN_WIDTH = 120
const MAX_WIDTH = 480

interface Props {
  pdfPath: string | null
  pageCount: number
  selectedPage: number
  onSelectPage: (page: number) => void
}

// Read-only single-file thumbnail strip for the Drive Upload preview - unlike
// SplitMode/MergeMode's panels, there's no rotate/skip/reorder here since
// Drive Upload doesn't edit pages, just files to their destination.
export default function DriveThumbnailPanel({ pdfPath, pageCount, selectedPage, onSelectPage }: Props) {
  const [panelWidth, setPanelWidth] = useState(DEFAULT_WIDTH)
  const startDrag = makeResizeDragHandler(panelWidth, setPanelWidth, MIN_WIDTH, MAX_WIDTH)
  const thumbWidth = panelWidth - ITEM_PADDING * 2
  const thumbHeight = Math.round(thumbWidth * PAGE_ASPECT)
  const itemHeight = thumbHeight + LABEL_HEIGHT + ITEM_PADDING

  const scrollRef = useRef<HTMLDivElement>(null)
  pageCache.usePageCacheRender()

  const virtualizer = useVirtualizer({
    count: pageCount,
    getScrollElement: () => scrollRef.current,
    estimateSize: () => itemHeight,
    overscan: 3,
  })

  useEffect(() => {
    virtualizer.measure()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [itemHeight, pageCount])

  // Keyed on the visible range so this only re-runs when scroll position, data, or
  // sizing actually change - same technique as the other ThumbnailPanels.
  useEffect(() => {
    if (!pdfPath) return
    for (const item of virtualizer.getVirtualItems()) pageCache.load(pdfPath, item.index + 1, thumbWidth)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [virtualizer.range?.startIndex, virtualizer.range?.endIndex, pdfPath, thumbWidth])

  useEffect(() => {
    if (pageCount > 0) virtualizer.scrollToIndex(selectedPage - 1, { align: 'auto' })
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedPage])

  useEffect(() => {
    if (!pdfPath) return
    const handler = (e: KeyboardEvent) => {
      if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) return
      if (e.key === 'ArrowLeft' && selectedPage > 1) { e.preventDefault(); onSelectPage(selectedPage - 1) }
      else if (e.key === 'ArrowRight' && selectedPage < pageCount) { e.preventDefault(); onSelectPage(selectedPage + 1) }
    }
    window.addEventListener('keydown', handler)
    return () => window.removeEventListener('keydown', handler)
  }, [pdfPath, selectedPage, pageCount, onSelectPage])

  return (
    <Box style={{ display: 'flex', height: '100%', flexShrink: 0 }}>
      <Box style={{ width: panelWidth, height: '100%', display: 'flex', flexDirection: 'column' }}>
        {!pdfPath ? (
          <Box
            style={{
              flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center',
              background: 'var(--mantine-color-gray-1)',
            }}
          >
            <Text size="sm" c="dimmed">Select a file to preview</Text>
          </Box>
        ) : (
          <div
            ref={scrollRef}
            style={{ flex: 1, minHeight: 0, overflowY: 'auto', overflowX: 'hidden', background: 'var(--mantine-color-gray-3)' }}
          >
            <div style={{ height: virtualizer.getTotalSize(), position: 'relative' }}>
              {virtualizer.getVirtualItems().map(item => {
                const page = item.index + 1
                return (
                  <div
                    key={item.key}
                    style={{ position: 'absolute', top: item.start, left: 0, width: '100%', height: item.size }}
                  >
                    <PageThumbnail
                      src={pageCache.getSrc(pdfPath, page)}
                      pdfPath={pdfPath}
                      page={page}
                      thumbHeight={thumbHeight}
                      isSelected={page === selectedPage}
                      isSkipped={false}
                      rotation={0}
                      isHovered={false}
                      label={String(page)}
                      onClick={() => onSelectPage(page)}
                      onRotate={() => {}}
                      onToggleSkip={() => {}}
                    />
                  </div>
                )
              })}
            </div>
          </div>
        )}
      </Box>

      <div
        onMouseDown={startDrag}
        style={{ width: DRAG_HANDLE_WIDTH, height: '100%', cursor: 'col-resize', flexShrink: 0, background: 'var(--mantine-color-gray-3)' }}
      />
    </Box>
  )
}

import { Box, Button, Group, Loader, Modal, Stack, Text } from '@mantine/core'
import TruncatedText from './TruncatedText'
import { LocalFile, LocalFileGroup, flattenFiles } from './useFileTree'
import * as uploadQueue from './uploadQueue'

interface Props {
  opened: boolean
  tree: LocalFileGroup
  onClose: () => void
}

// Read-only rendering of the tree for the duration of an upload run: no
// collapsing, no assignment badges, no click-to-preview. Status for every
// file lives in the uploadQueue module singleton, not in this component.
export default function UploadModal({ opened, tree, onClose }: Props) {
  uploadQueue.useUploadQueueRender()

  const allFiles = flattenFiles(tree)
  const settled = !allFiles.some(f => {
    const status = uploadQueue.getStatus(f.path)?.status
    return status === 'queued' || status === 'uploading'
  })

  return (
    <Modal
      opened={opened}
      onClose={onClose}
      title="Uploading to Drive"
      closeOnClickOutside={false}
      closeOnEscape={false}
      withCloseButton={false}
      size="md"
    >
      <Stack gap="md">
        <Stack gap={10}>
          {tree.files.map(file => <FileRow key={file.path} file={file} />)}
          {tree.subgroups.map(group => (
            <GroupSection key={group.name} group={group} groupKey={group.name} />
          ))}
        </Stack>
        <Group justify="flex-end">
          <Button variant="default" disabled={settled} onClick={() => uploadQueue.cancelRemaining()}>
            Cancel remaining
          </Button>
          <Button disabled={!settled} onClick={onClose}>
            Close
          </Button>
        </Group>
      </Stack>
    </Modal>
  )
}

function GroupSection({ group, groupKey }: { group: LocalFileGroup; groupKey: string }) {
  const groupFiles = flattenFiles(group)
  const doneCount = groupFiles.filter(f => uploadQueue.getStatus(f.path)?.status === 'done').length

  return (
    <Box pl={12}>
      <Group justify="space-between" gap={8} mb={4} wrap="nowrap">
        <TruncatedText label={group.name} size="sm" fw={600}>📁 {group.name}</TruncatedText>
        <Text size="xs" c="dimmed" style={{ flexShrink: 0 }}>{doneCount}/{groupFiles.length}</Text>
      </Group>
      <Stack gap={10}>
        {group.files.map(file => <FileRow key={file.path} file={file} />)}
        {group.subgroups.map(sub => (
          <GroupSection key={sub.name} group={sub} groupKey={`${groupKey}/${sub.name}`} />
        ))}
      </Stack>
    </Box>
  )
}

function FileRow({ file }: { file: LocalFile }) {
  const entry = uploadQueue.getStatus(file.path)
  const status = entry?.status ?? 'idle'

  return (
    <Group justify="space-between" wrap="nowrap" gap={8}>
      <TruncatedText label={file.name} size="sm" style={{ flex: 1, minWidth: 0 }}>{file.name}</TruncatedText>
      {status === 'queued' && <Text size="sm" c="dimmed">Queued</Text>}
      {status === 'uploading' && (
        <Group gap={6} wrap="nowrap">
          <Loader size="xs" />
          <Text size="sm" c="dimmed">Uploading…</Text>
        </Group>
      )}
      {status === 'done' && <Text size="sm" c="green">✓ Uploaded</Text>}
      {status === 'idle' && <Text size="sm" c="dimmed">Not uploaded</Text>}
      {status === 'error' && (
        <Group gap={8} wrap="nowrap">
          <TruncatedText label={entry?.error ?? ''} size="sm" c="red" style={{ maxWidth: 220 }}>
            ⚠ {entry?.error}
          </TruncatedText>
          <Button size="xs" variant="default" onClick={() => uploadQueue.retry(entry!)}>
            Retry
          </Button>
        </Group>
      )}
    </Group>
  )
}

import { useRef } from 'react'
import { Badge, Box, Tooltip } from '@mantine/core'
import { DriveAssignment } from './useDriveAssignments'
import { useIsTruncated } from '../../lib/useIsTruncated'

interface Props {
  label: string
  assignment: DriveAssignment | null
  isOwn: boolean
  onPick: () => void
  onClear: () => void
}

// Pinned to the right of its row (filename or folder header) by the caller,
// so badges land at a consistent horizontal position regardless of nesting
// depth - scannable as a column rather than a per-row detail.
export default function DriveAssignmentField({ label, assignment, isOwn, onPick, onClear }: Props) {
  const textRef = useRef<HTMLSpanElement>(null)
  const displayPath = assignment ? assignment.path : 'Not assigned'
  const truncated = useIsTruncated(textRef, displayPath)

  const badge = (
    <Badge
      component="button"
      type="button"
      onClick={onPick}
      aria-label={`Set Drive folder for ${label}`}
      color={assignment ? 'blue' : 'gray'}
      variant={isOwn ? 'light' : 'outline'}
      size="sm"
      radius="sm"
      style={{ cursor: 'pointer', fontWeight: isOwn ? 600 : 400, textTransform: 'none', maxWidth: 220 }}
      styles={{ label: { overflow: 'hidden' } }}
    >
      <span ref={textRef} style={{ display: 'block', overflow: 'hidden', textOverflow: 'ellipsis' }}>
        📁 {displayPath}
      </span>
    </Badge>
  )

  return (
    <Box style={{ display: 'flex', alignItems: 'center', gap: 4, flexShrink: 0 }}>
      {truncated ? <Tooltip label={displayPath} openDelay={500}>{badge}</Tooltip> : badge}
      {isOwn && (
        <button
          type="button"
          onClick={onClear}
          aria-label={`Clear Drive folder for ${label}`}
          style={{ border: 'none', background: 'transparent', padding: 0, cursor: 'pointer', flexShrink: 0, opacity: 0.6 }}
        >
          ✕
        </button>
      )}
    </Box>
  )
}

import { useState, useEffect } from 'react'
import { Box, Button, Checkbox, Group, Modal, SegmentedControl, Text, Tooltip } from '@mantine/core'
import { notifications } from '@mantine/notifications'
import { IconAlertTriangle } from '@tabler/icons-react'
import { MergePDFs, OpenFile, SavePDF } from '../../../wailsjs/go/main/App'
import MergeModeThumbnailPanel, { DEFAULT_TOTAL_WIDTH, FirstPageIn, SelectedPage } from './ThumbnailPanel'
import DetailPanel from '../DetailPanel'
import { usePDFFile } from './usePDFFile'
import * as pageCache from '../../lib/pageCache'
import { basename } from '../../utils'
import { DRAG_HANDLE_WIDTH } from '../../constants'

// Width consumed by the scrollbar inside the two-column thumbnail area.
const SCROLLBAR_WIDTH = 22

interface Props {
  onOpenInSplitMode: (path: string) => void
}

export default function MergeMode({ onOpenInSplitMode }: Props) {
  const fileA = usePDFFile()
  const fileB = usePDFFile()
  const [selectedPage, setSelectedPage] = useState<SelectedPage>({ file: 'a', page: 1 })
  const [firstPageIn, setFirstPageIn] = useState<FirstPageIn>('a')
  const [reverseB, setReverseB] = useState(true)
  const [merging, setMerging] = useState(false)
  const [mergedPath, setMergedPath] = useState<string | null>(null)
  const [totalWidth, setTotalWidth] = useState(DEFAULT_TOTAL_WIDTH)

  useEffect(() => {
    return () => {
      if (fileA.path) pageCache.evict(fileA.path)
      if (fileB.path) pageCache.evict(fileB.path)
    }
  }, [fileA.path, fileB.path])

  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) return
      const selectedFile = selectedPage.file === 'a' ? fileA : fileB
      if (e.key === 'ArrowLeft') {
        e.preventDefault()
        if (selectedPage.page > 1) setSelectedPage(p => ({ ...p, page: p.page - 1 }))
      } else if (e.key === 'ArrowRight') {
        e.preventDefault()
        if (selectedPage.page < selectedFile.count) setSelectedPage(p => ({ ...p, page: p.page + 1 }))
      } else if (e.key === 'Delete' || e.key === 'Backspace') {
        e.preventDefault()
        selectedFile.toggleSkip(selectedPage.page)
      }
    }
    window.addEventListener('keydown', handler)
    return () => window.removeEventListener('keydown', handler)
  }, [selectedPage, fileA, fileB])

  const colWidth = Math.floor((totalWidth - SCROLLBAR_WIDTH) / 2)

  const handleChoose = async (file: FirstPageIn) => {
    const loaded = await (file === 'a' ? fileA : fileB).load()
    if (loaded) setSelectedPage({ file, page: 1 })
  }

  const handleMerge = async () => {
    if (!fileA.path || !fileB.path) return
    const outPath = await SavePDF()
    if (!outPath) return
    setMerging(true)
    try {
      await MergePDFs(
        fileA.path, fileB.path, outPath,
        firstPageIn === 'a', reverseB,
        [...fileA.skipped], [...fileB.skipped],
        Object.fromEntries(fileA.rotations), Object.fromEntries(fileB.rotations),
      )
      setMergedPath(outPath)
    } catch (e) {
      notifications.show({ title: 'Merge failed', message: String(e), color: 'red' })
    } finally {
      setMerging(false)
    }
  }

  const bothLoaded = fileA.path !== null && fileB.path !== null
  const unequalCounts = bothLoaded && fileA.count !== fileB.count
  const selectedFile = selectedPage.file === 'a' ? fileA : fileB
  const selectedPath = selectedFile.path
  const selectedCount = selectedFile.count

  return (
    <Box style={{ display: 'flex', flexDirection: 'column', height: '100%' }}>
      <Modal opened={mergedPath !== null} onClose={() => setMergedPath(null)} title="Merge complete" centered>
        <Text size="sm" c="dimmed" mb="md">{mergedPath}</Text>
        <Group>
          <Button variant="default" onClick={() => OpenFile(mergedPath!)}>
            Open in Default App
          </Button>
          <Button onClick={() => { onOpenInSplitMode(mergedPath!); setMergedPath(null) }}>
            Open in Split Mode
          </Button>
        </Group>
      </Modal>
      <Box
        style={{
          flexShrink: 0,
          borderBottom: '1px solid var(--mantine-color-gray-3)',
          display: 'flex',
          alignItems: 'stretch',
        }}
      >
        <FilePickerColumn label="File A" path={fileA.path} width={colWidth} onChoose={() => handleChoose('a')} />
        <FilePickerColumn label="File B" path={fileB.path} width={colWidth + SCROLLBAR_WIDTH + DRAG_HANDLE_WIDTH} onChoose={() => handleChoose('b')} />
        <Group gap={8} px={12} style={{ flex: 1, justifyContent: 'flex-end' }}>
          {unequalCounts && (
            <Tooltip
              label={`File A has ${fileA.count} page${fileA.count !== 1 ? 's' : ''}, File B has ${fileB.count} page${fileB.count !== 1 ? 's' : ''}. The extra ${Math.abs(fileA.count - fileB.count)} page${Math.abs(fileA.count - fileB.count) !== 1 ? 's' : ''} will be appended at the end.`}
              multiline
              w={280}
            >
              <IconAlertTriangle size={18} color="var(--mantine-color-yellow-6)" />
            </Tooltip>
          )}
          <Checkbox
            size="sm"
            label="Reverse File B"
            checked={reverseB}
            onChange={(e) => setReverseB(e.currentTarget.checked)}
          />
          <Text size="sm" c="dimmed">First page in</Text>
          <SegmentedControl
            size="xs"
            value={firstPageIn}
            onChange={(v) => setFirstPageIn(v as FirstPageIn)}
            data={[
              { label: 'File A', value: 'a' },
              { label: 'File B', value: 'b' },
            ]}
          />
          <Button size="sm" disabled={!bothLoaded} loading={merging} onClick={handleMerge}>
            Merge & Save
          </Button>
        </Group>
      </Box>

      <Box style={{ flex: 1, overflow: 'hidden', display: 'flex' }}>
        <MergeModeThumbnailPanel
          fileA={fileA}
          fileB={fileB}
          selectedPage={selectedPage}
          onSelectPage={(file, page) => setSelectedPage({ file, page })}
          firstPageIn={firstPageIn}
          totalWidth={totalWidth}
          onWidthChange={setTotalWidth}
          colWidth={colWidth}
          reverseB={reverseB}
        />
        {selectedPath && (
          <DetailPanel
            pdfPath={selectedPath}
            pageNum={selectedPage.page}
            pageCount={selectedCount}
            rotation={selectedFile.rotations.get(selectedPage.page) ?? 0}
            onToggleSkip={() => selectedFile.toggleSkip(selectedPage.page)}
            onRotate={(delta) => selectedFile.rotate(selectedPage.page, delta)}
          />
        )}
      </Box>
    </Box>
  )
}

function FilePickerColumn({
  label, path, width, onChoose,
}: {
  label: string
  path: string | null
  width: number
  onChoose: () => void
}) {
  return (
    <Box
      style={{
        width,
        flexShrink: 0,
        padding: '6px 8px',
        borderRight: '1px solid var(--mantine-color-gray-3)',
        display: 'flex',
        flexDirection: 'column',
        justifyContent: 'center',
        gap: 2,
      }}
    >
      <Group justify="space-between" gap={4} wrap="nowrap">
        <Text size="xs" c="dimmed">{label}</Text>
        <Button size="xs" variant="default" onClick={onChoose}>Choose…</Button>
      </Group>
      <Text
        size="xs"
        style={{ overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}
        title={path ?? undefined}
      >
        {path ? basename(path) : '—'}
      </Text>
    </Box>
  )
}

